<?php
require_once __DIR__.'/helpers.php';require_once __DIR__.'/../includes/deployment_settings_helper.php';require_once __DIR__.'/../includes/auracle_platform_auth.php';
if(getenv('COOP_PLATFORM_MYSQL_TEST')!=='1'){fwrite(STDERR,"Set COOP_PLATFORM_MYSQL_TEST=1 for isolated platform settings tests.\n");exit(2);}
$server=new PDO('mysql:host=127.0.0.1;port=13307;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$server->exec('CREATE DATABASE IF NOT EXISTS coop_test_platform');$db=new PDO('mysql:host=127.0.0.1;port=13307;dbname=coop_test_platform;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
foreach(['auracle_platform_admins','auracle_platform_login_limits','coop_deployment_branding','coop_integration_configuration','coop_platform_configuration_history','coop_platform_configuration_commands','coop_branding_assets']as$table)$db->exec('DROP TABLE IF EXISTS '.$table);
$migration=file_get_contents(__DIR__.'/../database/migrations/20261021_platform_configuration.sql');$db->exec($migration);$db->exec($migration);
$cipher=new DeploymentSecretCipher(random_bytes(32));$principal=['id'=>7];$service=new DeploymentSettingsService($db,$cipher,fn($who)=>($who['id']??null)===7);$smtp=['host'=>'smtp.example.invalid','port'=>587,'encryption'=>'starttls','username'=>'synthetic-user','from_email'=>'test@example.invalid','from_name'=>'Synthetic cooperative'];
test('migration provisions no platform administrator and branding remains unconfigured',function()use($db,$service,$principal){assertSameValue(0,(int)$db->query('SELECT COUNT(*) FROM auracle_platform_admins')->fetchColumn());$settings=$service->settings($principal);assertSameValue(false,$settings['branding']['configured']);assertSameValue(0,$settings['branding']['revision']);});
test('cooperative administrator identity alone cannot configure platform settings',function()use($service){try{$service->settings(['id'=>3,'role'=>'Admin']);throw new LogicException('Cooperative admin accepted');}catch(RuntimeException$error){assertSameValue(403,$error->getCode());}});
test('branding persists with exact revision and command retry protection',function()use($service,$principal){$input=['cooperative_name'=>'Synthetic cooperative','primary_color'=>'#123ABC','accent_color'=>'#456DEF','logo_asset_id'=>null,'favicon_asset_id'=>null];$first=$service->saveBranding($principal,0,'branding-command-0001',$input);assertSameValue(1,$first['revision']);assertSameValue('#123abc',$first['primary_color']);assertSameValue($first,$service->saveBranding($principal,0,'branding-command-0001',$input));try{$input['cooperative_name']='Changed';$service->saveBranding($principal,0,'branding-command-0001',$input);throw new LogicException('Conflicting key accepted');}catch(RuntimeException$error){assertSameValue(409,$error->getCode());}});
test('credentials are encrypted in database and masked on settings reads',function()use($service,$principal,$smtp,$db,$cipher){$r=$service->saveIntegration($principal,'smtp',0,'smtp-command-000001',true,$smtp,['password'=>['action'=>'replace','value'=>'synthetic-password']]);assertSameValue(true,$r['secrets']['password']['configured']);$encrypted=$db->query("SELECT encrypted_secrets FROM coop_integration_configuration WHERE provider='smtp'")->fetchColumn();assertSameValue(false,strpos($encrypted,'synthetic-password')!==false);assertSameValue(false,strpos(json_encode($service->settings($principal)),'synthetic-password')!==false);assertSameValue('synthetic-password',deploymentIntegrationRuntime($db,'smtp',$cipher)['secrets']['password']);});
test('integration retry retains revision and never duplicates audit events',function()use($service,$principal,$smtp,$db){$before=(int)$db->query('SELECT COUNT(*) FROM coop_platform_configuration_history')->fetchColumn();$r=$service->saveIntegration($principal,'smtp',0,'smtp-command-000001',true,$smtp,['password'=>['action'=>'replace','value'=>'synthetic-password']]);assertSameValue(1,$r['revision']);assertSameValue($before,(int)$db->query('SELECT COUNT(*) FROM coop_platform_configuration_history')->fetchColumn());});
test('explicit retain and clear semantics prevent accidental secret replacement',function()use($service,$principal,$smtp,$db,$cipher){$service->saveIntegration($principal,'smtp',1,'smtp-retain-command02',true,$smtp,[]);assertSameValue('synthetic-password',deploymentIntegrationRuntime($db,'smtp',$cipher)['secrets']['password']);try{$service->saveIntegration($principal,'smtp',2,'smtp-bad-clear-key02',true,$smtp,['password'=>['action'=>'clear']]);throw new LogicException('Enabled connection lost credential');}catch(InvalidArgumentException$error){assertContains('credential',$error->getMessage());}$service->saveIntegration($principal,'smtp',2,'smtp-clear-command03',false,$smtp,['password'=>['action'=>'clear']]);assertSameValue(false,$service->settings($principal)['integrations']['smtp']['secrets']['password']['configured']);});
test('settings audit failure rolls back configuration and command marker',function()use($db,$service,$principal,$smtp){$db->exec("CREATE TRIGGER platform_audit_fail BEFORE INSERT ON coop_platform_configuration_history FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic audit failure'");try{try{$service->saveIntegration($principal,'smtp',3,'smtp-audit-failure04',false,$smtp,[]);throw new LogicException('Audit failure swallowed');}catch(PDOException$error){assertContains('Synthetic audit failure',$error->getMessage());}}finally{$db->exec('DROP TRIGGER platform_audit_fail');}assertSameValue(3,(int)$db->query("SELECT revision FROM coop_integration_configuration WHERE provider='smtp'")->fetchColumn());});
test('platform authentication accepts separately provisioned credentials and throttles failures',function()use($db){$stmt=$db->prepare('INSERT INTO auracle_platform_admins(username,password_hash)VALUES(?,?)');$stmt->execute(['synthetic-platform',password_hash('synthetic-platform-password',PASSWORD_DEFAULT)]);$auth=new AuraclePlatformAuth($db);$principal=$auth->login('synthetic-platform','synthetic-platform-password','192.0.2.10');assertSameValue('synthetic-platform',$principal['username']);for($i=0;$i<10;$i++){try{$auth->login('synthetic-platform','wrong','192.0.2.11');throw new LogicException('Wrong password accepted');}catch(RuntimeException$error){assertSameValue(401,$error->getCode());}}try{$auth->login('synthetic-platform','synthetic-platform-password','192.0.2.11');throw new LogicException('Throttle ignored');}catch(RuntimeException$error){assertSameValue(429,$error->getCode());}});
test('redacted audit and command history contain no plaintext credentials',function()use($db){foreach(['coop_platform_configuration_history','coop_platform_configuration_commands']as$table){$rows=$db->query('SELECT * FROM '.$table)->fetchAll(PDO::FETCH_ASSOC);assertSameValue(false,strpos(json_encode($rows),'synthetic-password')!==false);}});
finishTests();
